    const cur = rec ? rec.versions[rec.versions.length - 1] : null;
    if (baseVersion != null && baseVersion !== (cur ? cur.version : 0))
      throw new HttpError(409, 'conflict', 'version conflict', { currentVersion: cur ? cur.version : 0 });
